-- ========================================
-- ADD 45 LEVEL 5B AUTO STUDENTS TO GLOBAL STUDENT SHEETS
-- ========================================

-- Insert 45 Level 5B AUTO students
ON DUPLICATE KEY UPDATE 
  first_name = VALUES(first_name),
  last_name = VALUES(last_name),
  trade_code = VALUES(trade_code),
  level_number = VALUES(level_number);

-- Verify insertion
SELECT COUNT(*) as total_level5b_auto FROM global_student_sheets WHERE trade_code = 'AUTO' AND level_number = 5 AND level_suffix = 'B';
SELECT * FROM global_student_sheets WHERE trade_code = 'AUTO' AND level_number = 5 AND level_suffix = 'B' ORDER BY student_code;
